## Summary
- add `startRevisionBtn` id to the "Започни ревизия" button
- use `getElementById` to hide only this button when starting a revision

## Testing
- `node <<'NODE'
const {JSDOM} = require('jsdom');
const html = `
<div id="nameFields" style="display:block"></div>
<input id="barcodeInput" style="display:none">
<button id="startRevisionBtn" class="green-button" style="display:block"></button>
<button id="otherBtn" class="green-button" style="display:block"></button>`;
const dom = new JSDOM(html);
const document = dom.window.document;
document.getElementById('barcodeInput').focus = () => {};
global.sendActivity = function(){};
function startRevision(){
  sendActivity('start_revision');
  document.getElementById('nameFields').style.display='none';
  document.getElementById('barcodeInput').style.display='block';
  document.getElementById('startRevisionBtn').style.display='none';
  document.getElementById('barcodeInput').focus();
}
startRevision();
console.log('startRevisionBtn:', document.getElementById('startRevisionBtn').style.display);
console.log('otherBtn:', document.getElementById('otherBtn').style.display);
NODE`
